def report_counts(frame):
    global SAMPLE_SIZE_TEXT
    SAMPLE_SIZE_TEXT = ""
    ROW_COUNTS["prepared"] = len(frame)
    print(f"data: {DATA_PATH}, sha256 {DATA_HASH}")
    print(f"  {ROW_COUNTS.get('read', len(frame))} rows read")
    print(f"  {ROW_COUNTS.get('after_filter', len(frame))} rows after filter (" + "none" + ")")
    if len(frame) != ROW_COUNTS.get("after_filter", len(frame)):
        print(f"  {len(frame)} rows after reshape and transform")
    plot_keys = [field for field in ["epoch", "model"] if field in frame]
    ROW_COUNTS["missing_plot_keys"] = int(frame[plot_keys].isna().any(axis=1).sum()) if plot_keys else 0
    if ROW_COUNTS["missing_plot_keys"]:
        print(f"warning: {ROW_COUNTS['missing_plot_keys']} rows lack plotting keys and cannot be assigned to a point, panel or series")
    if SERIES_ORDER is not None and GROUP in frame:
        ROW_COUNTS["unlisted_series"] = [str(name) for name in frame[GROUP].dropna().unique() if name not in SERIES_ORDER]
    ROW_COUNTS["measurements"] = {}
    for field in ["accuracy"]:
        if field not in frame:
            continue
        finite = np.isfinite(pd.to_numeric(frame[field], errors="coerce").to_numpy(dtype=float))
        counts = {"finite": int(finite.sum()), "nonfinite": int((~finite).sum())}
        ROW_COUNTS["measurements"][field] = counts
        print(f"  {counts['finite']} rows with a finite {field} ({counts['nonfinite']} non-finite)")
    if "accuracy" in ROW_COUNTS["measurements"]:
        ROW_COUNTS.update(ROW_COUNTS["measurements"]["accuracy"])
    sizes = []
    keys = ["epoch", "model"]
    for field in ["accuracy"]:
        if field not in frame:
            continue
        source = summary_input(frame, field)
        measured = source.assign(_finite=np.isfinite(pd.to_numeric(source[field], errors="coerce")).astype(int))
        sizes.extend(measured.groupby(keys, sort=False, observed=True)["_finite"].sum().tolist())
    ROW_COUNTS["sample_sizes"] = [int(n) for n in sizes]
    if sizes:
        low, high = int(min(sizes)), int(max(sizes))
        SAMPLE_SIZE_TEXT = f"n = {low} per point" if low == high else f"n ranges from {low} to {high} across {len(sizes)} points"
        print(f"  {SAMPLE_SIZE_TEXT}")
        if low != high:
            print("warning: sample sizes differ between groups")


def summary_input(frame, field):
    measured = frame.copy()
    measured[field] = pd.to_numeric(measured[field], errors="coerce").replace([np.inf, -np.inf], np.nan)
    return measured


def summarise(frame):
    frame = summary_input(frame, Y_FIELD)
    keys = [X_FIELD] + ([GROUP] if GROUP is not None else [])
    # sort=False keeps the file's category order instead of an alphabetical one.
    grouped = frame.groupby(keys, as_index=False, sort=False, observed=True)[Y_FIELD]
    summary = grouped.mean()
    return summary


def locked_appearance(names):
    # A shared lock keeps a model the same colour in figure 1 and figure 7.
    if PALETTE_LOCK is None:
        return None
    try:
        from graphunslopify.lockfile import appearance
    except ImportError:
        print(diagnostic_text("palette_lock_unavailable", "The lockfile appearance helper is unavailable, so palette_lock was ignored."))
        return None
    return appearance(PALETTE_LOCK, [str(n) for n in names])


def series_names(frame):
    if GROUP is None:
        return [None]
    if SERIES_ORDER is not None:
        observed = sorted(frame[GROUP].dropna().unique().tolist(), key=str)
        return [n for n in SERIES_ORDER if n in observed] + [n for n in observed if n not in SERIES_ORDER]
    return sorted(frame[GROUP].dropna().unique().tolist(), key=str)


def series_style(name, index, total):
    locked = LOCKED.get(str(name)) if LOCKED else None
    colour = locked["colour"] if locked else PALETTE[index % len(PALETTE)]
    # Colour alone is not enough in greyscale, so add a second channel.
    if total <= SECOND_CHANNEL_THRESHOLD:
        channel = "-"
    elif EMPHASIS is None:
        channel = LINE_STYLES[index % len(LINE_STYLES)]
    else:
        # The emphasised series keeps the plain form, so the others must skip
        # it. Without this, series zero is also plain and the two collide.
        rest = LINE_STYLES[1:] or LINE_STYLES
        channel = rest[index % len(rest)]
    if locked and total > SECOND_CHANNEL_THRESHOLD:
        channel = locked["linestyle"]
    if name == EMPHASIS:
        channel = "-"
    if EMPHASIS is None:
        style = {"colour": colour, "width": 1.4, "alpha": 1.0, "zorder": 2}
    elif name == EMPHASIS:
        style = {"colour": colour, "width": 2.2, "alpha": 1.0, "zorder": 3}
    else:
        style = {"colour": colour, "width": 1, "alpha": RECEDED_ALPHA, "zorder": 1}
    style["linestyle"] = channel
    return style


def draw_panel(ax, df):
    frame = summarise(df)
    names = series_names(frame)
    for index, name in enumerate(names):
        block = frame[frame[GROUP] == name]
        block = block.sort_values(X_FIELD)
        style = series_style(name, index, len(names))
        _annotation_curve, = ax.plot(
            block[X_FIELD],
            block[Y_FIELD],
            label=str(name),
            color=style["colour"],
            linewidth=style["width"],
            alpha=style["alpha"],
            zorder=style["zorder"],
            linestyle=style["linestyle"],
            marker="o" if len(block) == 1 else None,
        )
        series_artist(_annotation_curve, name)


